code_sketch:
typedef struct { int fd; } fdoutbuf;
typedef struct { fdoutbuf *buf; } outstream;   /* the dependent part */

struct fdostream {                             /* payload declared first */
    fdoutbuf  buf;
    outstream stream;                          /* bound to &buf below */
};

void fdostream_init(struct fdostream *s, int fd) {
    fdoutbuf_init(&s->buf, fd);                /* step 1: payload exists */
    outstream_init(&s->stream, &s->buf);       /* step 2: dependent part */
}
